// front/app/page.tsx
"use client";

import { useEffect, useState } from "react";
import { getMovies, updateMovie } from "@/lib/api";
import MovieCard from "@/components/MovieCard";
import { Movie } from "@/types/movie";

export default function Home() {
  const [movies, setMovies] = useState<Movie[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [filter, setFilter] = useState<"all" | "watched" | "unwatched">("all");

  const loadMovies = async () => {
    const data = await getMovies();
    setMovies(data);
  };

  useEffect(() => {
    getMovies().then(setMovies);
    loadMovies();
  }, []);

  const markWatched = async (id: string) => {
    await updateMovie(id, { watched: true });
    setMovies((movies) =>
      movies.map((m) => (m.imdb_id === id ? { ...m, watched: true } : m)),
    );
  };

  const filteredMovies = movies.filter((movie) => {
    if (filter === "watched") return movie.watched;
    if (filter === "unwatched") return !movie.watched;
    return true; // "all"
  });

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "radial-gradient(circle at top, #111 0%, #000 60%)",
        color: "white",
        padding: "32px 16px",
      }}
    >
      <div
        style={{
          maxWidth: 1000,
          margin: "0 auto",
        }}
      >
        <div style={{ marginBottom: 32 }}>
          <h1 style={{ margin: 0, fontSize: 28 }}>🍿 WatchPop</h1>

          <p style={{ marginTop: 8, opacity: 0.7 }}>
            Your personal movie watchlist
          </p>
        </div>
        <div
          style={{
            display: "flex",
            gap: 12,
            marginBottom: 24,
          }}
        >
          {["all", "watched", "unwatched"].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f as any)}
              style={{
                padding: "8px 16px",
                borderRadius: 20,
                border: "1px solid #333",
                background: filter === f ? "#1976d2" : "transparent",
                color: filter === f ? "white" : "#bbb",
                cursor: "pointer",
                fontWeight: 500,
              }}
            >
              {f.charAt(0).toUpperCase() + f.slice(1)}
            </button>
          ))}
        </div>

        {message && (
          <div
            style={{
              position: "fixed",
              bottom: 24,
              right: 24,
              padding: "12px 16px",
              borderRadius: 10,
              background: "#1b5e20",
              color: "#c8e6c9",
              border: "1px solid #2e7d32",
              boxShadow: "0 8px 24px rgba(0,0,0,0.4)",
              zIndex: 1000,
              maxWidth: 320,
              transition: "opacity 0.3s ease",
            }}
          >
            {message}
          </div>
        )}

        <div style={{ display: "flex", flexDirection: "column" }}>
          {filteredMovies.map((movie) => (
            <MovieCard
              key={movie.imdb_id}
              movie={movie}
              onWatched={(msg: string) => {
                setMovies((prev) =>
                  prev.map((m) =>
                    m.imdb_id === movie.imdb_id
                      ? { ...m, watched: true, my_tags: m.my_tags }
                      : m,
                  ),
                );
                setMessage(msg);
                // auto-hide message after 3 seconds
                setTimeout(() => setMessage(null), 3000);
                loadMovies();
              }}
            />
          ))}
        </div>
      </div>
    </main>
  );
}
