// front/lib/api.ts
const API = "http://localhost:8000";

export async function getMovies() {
  const res = await fetch(`${API}/movies`);
  if (!res.ok) throw new Error("Failed to fetch movies");
  return res.json();
}

export async function updateMovie(
  imdb_id: string,
  payload: {
    watched?: boolean;
    rating?: number;
    my_tags?: string;
  },
) {
  return fetch(`${API}/movies/${imdb_id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
}

export async function discoverMovies(query: string) {
  if (!query) return [];

  const res = await fetch(
    `http://localhost:8000/discover/movies?query=${encodeURIComponent(query)}`,
  );

  if (!res.ok) {
    throw new Error("Discover failed");
  }

  return res.json();
}

export async function addMovie(imdb_id: string, friends_recommended: string[]) {
  const res = await fetch("http://localhost:8000/movies", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      imdb_id,
      friends_recommended: friends_recommended,
    }),
  });

  if (!res.ok) {
    throw new Error("Failed to add movie");
  }

  return res.json();
}
